import { PaymentRepository } from '../repositories/payment-repository.js';
import { OrderRepository } from '../repositories/order-repository.js';

const payments = new PaymentRepository();
const orders = new OrderRepository();

export function findPaymentsForUser(userId, callback) {
  orders.findByUser(userId)
    .then((rows) => Promise.all(rows.map((order) => payments.findByOrder(order.id))))
    .then((groups) => callback(null, groups.flat()), callback);
}

export function findPaymentsForOrder(orderId, callback) {
  payments.findByOrder(orderId).then((rows) => callback(null, rows), callback);
}

export function uncapturedTotalCents(callback) {
  payments.findUncaptured().then(
    (rows) => callback(null, rows.reduce((sum, payment) => sum + payment.amount_cents, 0)),
    callback,
  );
}
